'use strict';
(() => {
const api = window.clipboardLine;
const root = document.getElementById('app');
const overlays = document.getElementById('overlay-root');
const KINDS = ['image','text','link'];
const TITLES = {image:'Images',text:'Texts',link:'Links'};
const SYMBOLS = {image:'▧',text:'≡',link:'↗'};
const DEFAULT_KEYS = {
 library:'L',previous:'ArrowLeft',next:'ArrowRight',up:'ArrowUp',down:'ArrowDown',first:'Ctrl+ArrowLeft',last:'Ctrl+ArrowRight',
 previousPage:'Alt+ArrowLeft',nextPage:'Alt+ArrowRight',copy:'Ctrl+C',paste:'Ctrl+Enter',selectAll:'Ctrl+A',pin:'P',pinnedOnly:'F',
 preview:'Space',close:'Escape',switchShelf:'Tab',toggleShelves:'Ctrl+Shift+B',export:'Ctrl+Shift+E',trash:'Delete',remove:'S',undo:'Backspace',
 toggleLinks:'Shift+L',toggleTexts:'Shift+T',toggleImages:'Shift+I',folder:'Shift+P',name:'Alt+P',tag:'Ctrl+Shift+T',search:'Shift+S',
 librarySearch:'Ctrl+F',allTypes:'Ctrl+0',images:'Ctrl+1',texts:'Ctrl+2',links:'Ctrl+3',open:'Ctrl+O',edit:'E',copyOCR:'Ctrl+Shift+C',actions:'Ctrl+K',markup:'M',crop:'C',
 select:'V',pen:'B',marker:'H',rectangle:'R',ellipse:'O',arrow:'A',line:'D',annotationText:'T'
};
const ACTION_TITLES = {library:'Open Library',previous:'Previous item',next:'Next item',up:'Move up',down:'Move down',first:'First item',last:'Last item',previousPage:'Previous page',nextPage:'Next page',copy:'Copy',paste:'Paste into previous app',selectAll:'Select all',pin:'Pin',pinnedOnly:'Show pinned items',preview:'Preview',close:'Close',switchShelf:'Switch shelf',toggleShelves:'Toggle all shelves',export:'Export copies',trash:'Move to Trash',remove:'Take down',undo:'Undo take down',toggleLinks:'Toggle Links',toggleTexts:'Toggle Texts',toggleImages:'Toggle Images',folder:'Pin to folder',name:'Name and pin',tag:'Add tags',search:'Search shelves',librarySearch:'Search Library',allTypes:'All types',images:'Images',texts:'Texts',links:'Links',open:'Open in browser',edit:'Edit text',copyOCR:'Copy text from image',actions:'Actions',markup:'Image markup',crop:'Crop image',select:'Select annotation',pen:'Pen',marker:'Marker',rectangle:'Rectangle',ellipse:'Ellipse',arrow:'Arrow',line:'Line',annotationText:'Text annotation'};
const TR = {'Images':'Görseller','Texts':'Metinler','Links':'Linkler','Library':'Kütüphane','Open Library':'Kütüphaneyi aç','Settings':'Ayarlar','Actions':'Eylemler','Search':'Ara','Search shelves':'Askılarda ara','Search Library':'Kütüphanede ara','My library':'Kütüphanem','Recent copies':'Son kopyalar','Pinned':'Sabitlenenler','Unorganized':'Düzenlenmemiş','Trash':'Çöp Kutusu','Folders':'Klasörler','Tags':'Etiketler','New folder':'Yeni klasör','New note':'Yeni not','Import':'İçe aktar','Screenshot':'Ekran görüntüsü','Hide':'Gizle','Close':'Kapat','Copy':'Kopyala','Paste into previous app':'Önceki uygulamaya yapıştır','Preview':'Önizleme','Pin':'Sabitle','Unpin':'Sabitlemeyi kaldır','Name and pin':'Adlandır ve sabitle','Pin to folder':'Klasöre ekleyerek sabitle','Add tags':'Etiket ekle','Take down':'Askıdan kaldır','Undo take down':'Kaldırmayı geri al','Export copies':'Kopyaları dışa aktar','Move to Trash':'Çöp Kutusu’na taşı','Restore':'Geri getir','Delete permanently':'Kalıcı sil','Cancel':'İptal','Save':'Kaydet','Save and next':'Kaydet ve sıradaki','Done':'Bitti','No matching items':'Eşleşen öğe yok','No items yet':'Henüz öğe yok','Try another search or filter.':'Başka arama veya filtre dene.','Copy something or import a file to get started.':'Başlamak için bir şey kopyala veya dosya aktar.','General':'Genel','History':'Geçmiş','Sources':'Kaynaklar','Keyboard shortcuts':'Klavye kısayolları','Updates':'Güncellemeler','About':'Hakkında','All types':'Tüm türler','Newest first':'Önce en yeni','Oldest first':'Önce en eski','Title':'Başlık','Last copied':'Son kopyalanan','Type':'Tür','Name':'Ad','Content':'İçerik','Note':'Not','Apply':'Uygula','Clear filters':'Filtreleri temizle','Grid':'Izgara','List':'Liste','Show pinned items':'Sabitlenenleri göster','Open in browser':'Tarayıcıda aç','Image markup':'Görsel işaretleme','Crop image':'Görseli kırp','Copy text from image':'Görseldeki yazıyı kopyala','Copied':'Kopyalandı','Check for updates':'Güncellemeleri kontrol et','Install update':'Güncellemeyi kur','Language':'Dil','Colors':'Renkler','Soft colors':'Yumuşak renkler','Neutral glass':'Nötr cam','Card size':'Kart boyutu','Small':'Küçük','Medium':'Orta','Large':'Büyük','Record shortcut':'Kısayol kaydet','Reset':'Sıfırla','Off':'Kapalı','Keep forever':'Süresiz tut','Pin without folder':'Klasörsüz sabitle','Search folders…':'Klasör ara…','Search actions…':'Eylem ara…','Search visible shelves…':'Görünür askılarda ara…','Search library…':'Kütüphanede ara…','Edit text':'Metni düzenle','No matching actions':'Eşleşen eylem yok'};
const ui = {view:'shelves',active:'image',selected:new Set(),focus:null,anchor:null,pages:{image:0,text:0,link:0},pinned:{image:false,text:false,link:false},search:'',searchOpen:false,scope:'saved',type:'all',folder:null,tag:null,days:0,domain:'',sort:'newest',list:false,preview:null,editingText:false,textDraft:'',editor:null,modal:null,settingsTab:'general',shortcutsQuery:'',zoom:1,pan:{x:0,y:0},justHidden:false,lastEvent:'',undoFocus:[],busy:false};
let state = {items:[],folders:[],settings:{visibleKinds:KINDS,retentionDays:{image:30,text:30,link:30},shortcuts:{},localShortcuts:{}},view:'shelves',version:'',canUndo:false};
let toastTimer, pointer=null, annotationSequence=0, lastVisibility=null;
const t = text => state.settings.language==='tr' ? TR[text] || text : text;
const esc = value => String(value ?? '').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const attr = esc;
const fold = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
const item = id => state.items.find(value=>value.id===id);
const saved = value => value.pinned || value.folderIds?.length || value.tags?.length;
const title = value => value.name || value.title || (value.kind==='text' ? value.text?.split('\n')[0] : value.kind==='link' ? value.url : 'Image') || 'Untitled';
const thumbnail = value => { const url=value?.thumbnailUrl || value?.mediaUrl || ''; return /^appmedia:\/\/media\/[a-f0-9-]+(?:\/original|\/thumbnail)?(?:\?[^\s]*)?$/.test(url) || /^data:image\/(png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(url) ? url : ''; };
const hotkey = action => state.settings.localShortcuts?.[action] ?? DEFAULT_KEYS[action] ?? '';
const keyHint = action => hotkey(action) ? `<kbd>${esc(hotkey(action).replaceAll('Arrow',''))}</kbd>` : '';
function toast(message) { const target=document.getElementById('toast'); target.textContent=message; target.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>target.classList.remove('visible'),3500); }
function visibleKinds() { return state.settings.visibleKinds?.length ? KINDS.filter(kind=>state.settings.visibleKinds.includes(kind)) : KINDS; }
function matches(value,query) { const hay=fold([value.name,value.title,value.text,value.url,value.note,value.ocrText,...(value.tags||[])].join(' ')); return fold(query).trim().split(/\s+/).every(token=>hay.includes(token)); }
function rowItems(kind) { return state.items.filter(value=>value.kind===kind && !value.trashedAt && !value.hiddenFromShelf && (!ui.pinned[kind]||value.pinned) && (!ui.search||matches(value,ui.search))).sort((a,b)=>b.createdAt-a.createdAt); }
function folderIncludes(value,id) { const ids=new Set([id]); let changed=true; while(changed){changed=false; for(const folder of state.folders)if(ids.has(folder.parentId)&&!ids.has(folder.id)){ids.add(folder.id);changed=true;}} return value.folderIds?.some(folder=>ids.has(folder)); }
function libraryItems() { return state.items.filter(value=>{
 if(ui.scope==='trash' ? !value.trashedAt : value.trashedAt)return false;
 if(ui.scope==='saved'&&!saved(value))return false;
 if(ui.scope==='pinned'&&!value.pinned)return false;
 if(ui.scope==='unorganized'&&(value.folderIds?.length||value.tags?.length))return false;
 if(ui.scope==='folder'&&!folderIncludes(value,ui.folder))return false;
 if(ui.scope==='tag'&&!value.tags?.includes(ui.tag))return false;
 if(ui.type!=='all'&&value.kind!==ui.type)return false;
 if(ui.days&&value.createdAt<Date.now()-ui.days*86400000)return false;
 if(ui.domain){try{const host=new URL(value.url).hostname.replace(/^www\./,'');const wanted=ui.domain.replace(/^www\./,'').toLowerCase();if(host!==wanted&&!host.endsWith('.'+wanted))return false;}catch{return false;}}
 return !ui.search||matches(value,ui.search);
 }).sort((a,b)=>ui.sort==='oldest'?a.createdAt-b.createdAt:ui.sort==='title'?title(a).localeCompare(title(b)):ui.sort==='copied'?(b.copiedAt||b.updatedAt)-(a.copiedAt||a.updatedAt):b.createdAt-a.createdAt); }
function currentItems() { return ui.view==='library'?libraryItems():rowItems(ui.active); }
function selectedIds() { if(ui.preview)return [ui.preview]; const values=currentItems(); const selected=values.filter(value=>ui.selected.has(value.id)).map(value=>value.id); return selected.length?selected:(ui.focus?[ui.focus]:[]); }
function focusFirst() { const kinds=visibleKinds(); if(!kinds.includes(ui.active))ui.active=kinds[0]||'image'; const first=currentItems()[0]; ui.selected=new Set(first?[first.id]:[]); ui.focus=first?.id||null; ui.anchor=ui.focus; ui.pages={image:0,text:0,link:0}; }
function applyState(next) {
 if(!next || !Array.isArray(next.items))return;
 const previousView=ui.view; const wasHidden=lastVisibility===false&&next.windowVisible===true; lastVisibility=next.windowVisible ?? lastVisibility; state=next; if(['shelves','library','settings'].includes(next.view))ui.view=next.view;
 const signature=next.viewEvent?JSON.stringify(next.viewEvent):'';
 if(signature&&signature!==ui.lastEvent){ui.lastEvent=signature;const event=next.viewEvent;if(event.selectId){ui.active=event.kind||item(event.selectId)?.kind||ui.active;ui.focus=event.selectId;ui.selected=new Set([event.selectId]);ui.preview=event.preview?event.selectId:null;ui.editingText=false;ui.editor=null;ui.zoom=1;ui.pan={x:0,y:0};if(event.crop)setTimeout(()=>beginImageEdit('crop'),0);}if(event.search){ui.searchOpen=true;setTimeout(()=>document.getElementById('search-input')?.focus(),0);}}
 if(ui.justHidden||wasHidden||previousView!==ui.view){ui.justHidden=false;if(!ui.preview)focusFirst();}
 if(ui.focus&&!item(ui.focus))ui.focus=null;
 if(!ui.focus&&!ui.preview)focusFirst();
 render();
}
async function command(action,payload={}) { try { const next=await api.command(action,payload);if(next?.items)applyState(next);if(next?.result?.error){toast(next.result.error);return null;}return next; } catch(error){toast(error?.message||'The action could not be completed.');return null;} }
function button(action,label,extra='') { return `<button data-action="${action}" ${extra}>${esc(t(label))}</button>`; }
function topbar() { return `<header class="topbar"><span class="brand">ClipBoardLine</span><button data-action="shelves" class="${ui.view==='shelves'?'active':''}">${esc(t('Images'))} · ${esc(t('Texts'))} · ${esc(t('Links'))}</button>${button('library','Library',ui.view==='library'?'class="active"':'')}<div class="grow"></div><div class="toolbar">${button('actions','Actions')}<button data-action="search" title="${attr(hotkey('search'))}">⌕ <span class="label">${esc(t('Search'))}</span></button>${button('capture','Screenshot')}${button('import','Import')}${button('settings','Settings')}${button('hide','Hide','class="quiet"')}</div></header>`; }
function card(value,index,library=false) {
 const image=thumbnail(value); const body=value.kind==='image'?`<img src="${attr(image)}" alt="${attr(title(value))}" loading="lazy" draggable="false">`:value.kind==='text'?`${value.name?`<div class="card-title">${esc(value.name)}</div>`:''}<div class="card-body">${esc(value.text)}</div>`:`${image?`<img class="link-thumb" src="${attr(image)}" alt="" loading="lazy" draggable="false">`:''}<div class="card-title">${esc(title(value))}</div><div class="card-caption">${esc(hostname(value.url))}</div>`;
 return `<article class="card kind-${value.kind} ${ui.focus===value.id?'focused':''} ${ui.selected.has(value.id)?'selected':''}" data-item-id="${attr(value.id)}" tabindex="0" role="option" aria-selected="${ui.selected.has(value.id)}" aria-label="${attr(title(value))}" draggable="true">${body}${value.kind==='image'&&value.name?`<div class="card-caption">${esc(value.name)}</div>`:''}<div class="card-controls"><button data-action="card-pin" data-id="${value.id}" class="${value.pinned?'pinned':''}" aria-label="${attr(t(value.pinned?'Unpin':'Pin'))}" title="${attr(t(value.pinned?'Unpin':'Pin'))}">${value.pinned?'◆':'◇'}</button><button data-action="card-remove" data-id="${value.id}" aria-label="${attr(t('Take down'))}" title="${attr(t('Take down'))}">×</button></div>${!library&&index<9?`<span class="card-number" aria-hidden="true">${index+1}</span>`:''}</article>`;
}
function hostname(url) { try{return new URL(url).hostname.replace(/^www\./,'');}catch{return '';}}
function empty() { return `<div class="empty"><strong>${esc(t(ui.search?'No matching items':'No items yet'))}</strong><span>${esc(t(ui.search?'Try another search or filter.':'Copy something or import a file to get started.'))}</span></div>`; }
function shelves() { return `${ui.searchOpen?`<div class="search-hud"><span class="search-symbol" aria-hidden="true">⌕</span><input id="search-input" data-focus="shelf-search" placeholder="${attr(t('Search visible shelves…'))}" value="${attr(ui.search)}" aria-label="${attr(t('Search shelves'))}"><small>${visibleKinds().reduce((n,kind)=>n+rowItems(kind).length,0)}</small>${button('close-search','Close','class="quiet"')}</div>`:''}<main class="content shelves" aria-label="Clipboard shelves">${visibleKinds().map(kind=>{
 const values=rowItems(kind);const max=Math.max(0,Math.ceil(values.length/9)-1);ui.pages[kind]=Math.min(ui.pages[kind],max);const page=ui.pages[kind]||0;return `<section class="shelf ${ui.active===kind?'active-shelf':''}" data-shelf="${kind}" aria-label="${attr(t(TITLES[kind]))}"><div class="shelf-head"><button class="shelf-title quiet" data-action="activate-shelf" data-kind="${kind}"><span>${SYMBOLS[kind]}</span>${esc(t(TITLES[kind]))}<span class="shelf-count">${values.length}</span></button><div class="grow"></div><button class="quiet" data-action="pinned-kind" data-kind="${kind}" aria-pressed="${ui.pinned[kind]}" title="${attr(t('Show pinned items'))}">◆</button><button data-action="page-back" data-kind="${kind}" class="quiet" ${!page?'disabled':''} aria-label="Previous page">‹</button><span class="selection-info">${values.length?page+1:0} / ${Math.max(1,max+1)}</span><button data-action="page-next" data-kind="${kind}" class="quiet" ${page>=max?'disabled':''} aria-label="Next page">›</button></div><div class="line" aria-hidden="true"></div><div class="cards" role="listbox" aria-label="${attr(t(TITLES[kind]))}" aria-multiselectable="true">${values.length?values.slice(page*9,page*9+9).map((value,index)=>card(value,index)).join(''):empty()}</div></section>`;
 }).join('')}</main>`; }
function sidebar() { const scopes=[['saved','My library'],['recent','Recent copies'],['pinned','Pinned'],['unorganized','Unorganized'],['trash','Trash']];const tags=[...new Set(state.items.filter(value=>!value.trashedAt).flatMap(value=>value.tags||[]))].sort();return `<aside class="sidebar" aria-label="Library navigation">${scopes.map(([scope,label])=>`<button data-action="scope" data-scope="${scope}" class="${ui.scope===scope?'active':'quiet'}">${esc(t(label))}</button>`).join('')}<h2>${esc(t('Folders'))}</h2>${state.folders.map(folder=>`<div class="folder-row"><button data-action="folder-scope" data-folder="${folder.id}" class="${ui.scope==='folder'&&ui.folder===folder.id?'active':'quiet'}" style="padding-left:${11+(folder.parentId?12:0)}px" title="${attr(folderPath(folder.id))}">▱ ${esc(folder.name)}</button><button class="quiet" data-action="folder-menu" data-folder="${folder.id}" aria-label="Folder actions">⋯</button></div>`).join('')}${button('new-folder','New folder','class="quiet"')}<h2>${esc(t('Tags'))}</h2>${tags.map(tag=>`<button data-action="tag-scope" data-tag="${attr(tag)}" class="${ui.scope==='tag'&&ui.tag===tag?'active':'quiet'}"># ${esc(tag)}</button>`).join('')}</aside>`; }
function library() { const values=libraryItems();return `<main class="content library">${sidebar()}<section class="library-main" aria-label="Library results"><div class="library-controls"><input id="search-input" data-focus="library-search" value="${attr(ui.search)}" placeholder="${attr(t('Search library…'))}" aria-label="${attr(t('Search Library'))}"><select id="type-filter" aria-label="${attr(t('Type'))}">${[['all','All types'],['image','Images'],['text','Texts'],['link','Links']].map(([value,label])=>`<option value="${value}" ${ui.type===value?'selected':''}>${esc(t(label))}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort">${[['newest','Newest first'],['oldest','Oldest first'],['title','Title'],['copied','Last copied']].map(([value,label])=>`<option value="${value}" ${ui.sort===value?'selected':''}>${esc(t(label))}</option>`).join('')}</select><button data-action="view-mode" title="${attr(t(ui.list?'Grid':'List'))}">${ui.list?'▦':'☷'}</button>${button('new-note','New note')}</div><div class="filter-row"><select id="date-filter" aria-label="Filter by date"><option value="0">Any date</option>${[1,7,30].map(days=>`<option value="${days}" ${ui.days===days?'selected':''}>Last ${days} days</option>`).join('')}</select><input id="domain-filter" data-focus="domain" value="${attr(ui.domain)}" placeholder="Domain, e.g. youtube.com" aria-label="Domain filter"><button data-action="clear-filters" class="quiet">${esc(t('Clear filters'))}</button><span class="selection-info">${values.length} ${esc(t('items'))}</span></div><div class="library-results"><div class="library-grid ${ui.list?'list':''}" role="listbox" aria-label="Library items" aria-multiselectable="true">${values.length?values.map((value,index)=>card(value,index,true)).join(''):empty()}</div></div></section>${inspector()}</main>`; }
function inspector() { const ids=selectedIds(), value=ids.length===1?item(ids[0]):null;return `<aside class="inspector" aria-label="Item details"><h2>${esc(value?title(value):`${ids.length} selected`)}</h2>${value?`<p>${esc(t(TITLES[value.kind]))} · ${esc(new Date(value.createdAt).toLocaleString())}</p><label for="detail-name">${esc(t('Name'))}</label><input id="detail-name" data-focus="detail-name" value="${attr(value.name||'')}" placeholder="Name this item"><button data-action="save-detail-name" style="margin-top:8px">${esc(t('Name and pin'))}</button>${value.kind==='text'?`<label for="detail-text">${esc(t('Content'))}</label><textarea id="detail-text" data-focus="detail-text" rows="8">${esc(value.text)}</textarea><button data-action="save-detail-text" style="margin-top:8px">${esc(t('Save'))}</button>`:''}<p>${(value.tags||[]).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</p><p>${(value.folderIds||[]).map(id=>esc(folderPath(id))).join('<br>')}</p>`:'<p>Choose items to copy, organize or export.</p>'}<div class="note-actions">${button('copy','Copy',!ids.length?'disabled':'')}${button('pin','Pin',!ids.length?'disabled':'')}${button('folder','Pin to folder',!ids.length?'disabled':'')}${button('tag','Add tags',!ids.length?'disabled':'')}${button('export','Export copies',!ids.length?'disabled':'')}${ui.scope==='trash'?button('restore','Restore',!ids.length?'disabled':'')+button('delete','Delete permanently',!ids.length?'disabled':'class="danger"'):button('trash','Move to Trash',!ids.length?'disabled':'class="danger"')}</div></aside>`; }
function settingRow(label,control,description='') { return `<div class="setting-row"><div class="setting-description"><strong>${esc(t(label))}</strong>${description?`<small>${esc(description)}</small>`:''}</div>${control}</div>`; }
function toggle(name,label,description='') {return settingRow(label,`<input type="checkbox" data-setting="${name}" ${state.settings[name]?'checked':''} aria-label="${attr(label)}">`,description);}
function settings() { const section=ui.settingsTab;const s=state.settings;let body='';if(section==='general')body=`<div class="settings-group">${settingRow('Language',`<select data-setting="language"><option value="en" ${s.language!=='tr'?'selected':''}>English</option><option value="tr" ${s.language==='tr'?'selected':''}>Türkçe</option></select>`)}${settingRow('Colors',`<select data-setting="theme"><option value="soft" ${s.theme!=='neutral'?'selected':''}>${esc(t('Soft colors'))}</option><option value="neutral" ${s.theme==='neutral'?'selected':''}>${esc(t('Neutral glass'))}</option></select>`)}${settingRow('Card size',`<select data-setting="cardSize">${['small','medium','large'].map(size=>`<option value="${size}" ${(s.cardSize||'medium')===size?'selected':''}>${esc(t(size[0].toUpperCase()+size.slice(1)))}</option>`).join('')}</select>`)}${toggle('openAfterScreenshot','Open after screenshot','Focus the captured image immediately so Enter and Space work.')}${toggle('sounds','Sounds')}${toggle('launchAtLogin','Launch at login')}</div><div class="settings-group">${KINDS.map(kind=>settingRow(TITLES[kind],`<input type="checkbox" data-visible-kind="${kind}" ${visibleKinds().includes(kind)?'checked':''} aria-label="${attr(t(TITLES[kind]))}">`)).join('')}</div>`;
 else if(section==='sources')body=`<div class="settings-group">${toggle('captureImages','Capture copied images')}${toggle('captureText','Capture copied text','Text copies never open the shelves automatically.')}${toggle('captureLinks','Capture copied links','A standalone URL becomes a link; paragraphs remain text.')}${toggle('fetchLinkMetadata','Fetch link titles and thumbnails','Optional network access to the linked public website or YouTube.')}${toggle('indexImages','Recognize text in new images','On-device OCR indexes new images for search.')}</div><div class="settings-group">${(s.watchFolders||[]).map(folder=>settingRow(folder,`<button data-action="remove-watch-folder" data-path="${attr(folder)}">×</button>`)).join('')}${settingRow('Watch image folders',button('choose-watch-folder','Add folder'),'External originals stay in place.')}</div><p>Private clipboard markers are ignored. YouTube/site metadata may contact the public linked website; OCR runs locally.</p>`;
 else if(section==='history')body=`<div class="settings-group">${KINDS.map(kind=>settingRow(TITLES[kind],`<select data-retention="${kind}" aria-label="${attr(t(TITLES[kind]))}">${[1,3,7,15,30,0].map(days=>`<option value="${days}" ${Number(s.retentionDays[kind])===days?'selected':''}>${days?`${days} days`:esc(t('Keep forever'))}</option>`).join('')}</select>`)).join('')}</div><p>Pins, folders and tags retain records beyond these time limits. Unsaved expired copies move to recoverable Trash.</p>`;
 else if(section==='shortcuts')body=`<p>Windows uses Control for copy, paste and app commands. Record a combination or turn an action off. Letter keys work only while browsing.</p><div class="settings-group">${Object.entries(s.shortcuts||{}).map(([action,key])=>settingRow(action==='toggle'?'Show/hide globally':action==='search'?'Search globally':'Screenshot globally',`<button class="key-record" data-action="record-global" data-key-action="${action}">${esc(key||t('Off'))}</button>`)).join('')}</div><input class="shortcut-filter" id="shortcut-filter" data-focus="shortcut-filter" placeholder="Find shortcut…" value="${attr(ui.shortcutsQuery)}"><div class="shortcut-grid">${Object.keys(DEFAULT_KEYS).filter(action=>fold(ACTION_TITLES[action]).includes(fold(ui.shortcutsQuery))).map(action=>settingRow(ACTION_TITLES[action],`<button class="key-record" data-action="record-local" data-key-action="${action}">${esc(hotkey(action)||t('Off'))}</button>`)).join('')}</div><button data-action="reset-local-shortcuts">${esc(t('Reset'))}</button>`;
 else if(section==='updates')body=`<div class="settings-group">${toggle('autoCheckUpdates','Automatically check for updates','Checks while the app runs. Installation requires your action.')}${settingRow('App updates',`<button data-action="check-updates">${esc(t('Check for updates'))}</button>`,state.update?.message||'Signed public updates; no account or token required.')}${['available','ready'].includes(state.update?.status)?settingRow(state.update.version||'New version',button('install-update','Install update')):''}</div><p>Windows uses its own signed installer channel. Your library and settings stay on this PC.</p>`;
 else body=`<h2>ClipBoardLine ${esc(state.version)}</h2><p>Local clipboard shelves and a saved library for Windows.</p><div class="settings-group">${settingRow('Source ancestry','Tendedero · MIT','Based on Alejandro Buján’s Tendedero; separate name and artwork.')}${settingRow('Workflow inspiration','Tangerine / Nashi','Inspired workflow and native update experience; not an endorsement.')}${settingRow('Recognition','Tesseract OCR','English and Turkish recognition runs on this PC.')}</div><p>The Windows implementation does not use Apple Vision or Core ML. Semantic image search is not available in this port.</p>`;
 return `<main class="content settings"><aside class="settings-tabs" aria-label="Settings sections">${[['general','General'],['sources','Sources'],['history','History'],['shortcuts','Keyboard shortcuts'],['updates','Updates'],['about','About']].map(([key,label])=>`<button class="${section===key?'active':'quiet'}" data-action="settings-tab" data-tab="${key}">${esc(t(label))}</button>`).join('')}</aside><section class="settings-main"><h1>${esc(t(section==='shortcuts'?'Keyboard shortcuts':section[0].toUpperCase()+section.slice(1)))}</h1>${body}</section></main>`; }
function render() { const focused=document.activeElement;const identity=focused?.dataset?.focus;const focusedId=focused?.id;const oldValue=isEditor(focused)?focused.value:null;const selection=(identity||focusedId)&&typeof focused.selectionStart==='number'?[focused.selectionStart,focused.selectionEnd]:null;root.className=`${state.settings.theme==='neutral'?'neutral':''} size-${state.settings.cardSize||'medium'}`;root.innerHTML=`<div class="shell">${topbar()}${ui.view==='settings'?settings():ui.view==='library'?library():shelves()}<footer class="statusbar"><span>${selectedIds().length} selected</span><div class="grow"></div><div class="key-legend"><span><kbd>Space</kbd> ${esc(t('Preview'))}</span><span><kbd>Enter</kbd> ${esc(t('Copy'))}</span><span>${keyHint('pin')} ${esc(t('Pin'))}</span><span>${keyHint('actions')} ${esc(t('Actions'))}</span></div></footer></div>`;root.setAttribute('aria-busy','false');renderOverlay();if(identity||focusedId){const next=focusedId?document.getElementById(focusedId):root.querySelector(`[data-focus="${identity}"]`);if(next&&oldValue!=null&&isEditor(next))next.value=oldValue;next?.focus();if(selection&&next?.setSelectionRange)try{next.setSelectionRange(...selection);}catch{}}}
function folderPath(id) { const names=[];const visited=new Set();while(id&&!visited.has(id)){visited.add(id);const folder=state.folders.find(value=>value.id===id);if(!folder)break;names.unshift(folder.name);id=folder.parentId;}return names.join(' / '); }
function dialog(titleText,body,footer='',className='') {return `<div class="modal-backdrop"><section class="dialog ${className}" role="dialog" aria-modal="true" aria-label="${attr(t(titleText))}"><header><h2>${esc(t(titleText))}</h2><div class="grow"></div><button class="quiet" data-action="close-modal" aria-label="${attr(t('Close'))}">×</button></header><div class="dialog-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;}
function openModal(value) {ui.modal=value;renderOverlay();setTimeout(()=>overlays.querySelector('input,textarea,button.dialog-option')?.focus(),0);}
function closeModal(){ui.modal=null;renderOverlay();}
function currentModalOptions(){const modal=ui.modal;if(!modal)return[];if(modal.type==='actions')return actionCommands().filter(value=>matchesCommand(value,modal.query||''));if(modal.type==='folder')return [{id:'',name:t('Pin without folder')},...state.folders.map(folder=>({id:folder.id,name:folderPath(folder.id)}))].filter(value=>fold(value.name).includes(fold(modal.query||'')));return[];}
function matchesCommand(value,query){return fold(query).split(/\s+/).every(token=>fold(value.title+' '+(value.detail||'')).includes(token));}
function renderOverlay(){if(ui.modal){const modal=ui.modal;let html='';if(modal.type==='actions'){const options=currentModalOptions();modal.index=Math.max(0,Math.min(modal.index||0,options.length-1));html=dialog('Actions',`<input class="palette-input" id="modal-query" placeholder="${attr(t('Search actions…'))}" value="${attr(modal.query||'')}" aria-label="Search actions"><div class="dialog-list">${options.length?options.map((value,index)=>`<button class="dialog-option ${modal.index===index?'selected':''}" data-action="execute-command" data-command="${value.id}" ${value.disabled?'disabled':''}><span class="option-icon">${value.icon||'⌘'}</span><span class="grow"><span class="title">${esc(t(value.title))}</span><small>${esc(value.detail||'')}</small></span>${value.key?`<kbd>${esc(value.key)}</kbd>`:''}</button>`).join(''):`<p>${esc(t('No matching actions'))}</p>`}</div>`,`<span><kbd>↑ ↓</kbd> Browse</span><span><kbd>Enter</kbd> Run · <kbd>Esc</kbd> Close</span>`,'palette');}
else if(modal.type==='folder'){const options=currentModalOptions();modal.index=Math.max(0,Math.min(modal.index||0,options.length-1));html=dialog('Pin to folder',`<p>${modal.ids.length} selected · <kbd>Ctrl+N</kbd> ${esc(t('New folder'))}</p><input id="modal-query" placeholder="${attr(t('Search folders…'))}" value="${attr(modal.query||'')}" aria-label="Search folders"><div class="dialog-list">${options.map((folder,index)=>`<button class="dialog-option ${modal.index===index?'selected':''}" data-action="choose-folder" data-folder="${attr(folder.id)}"><span class="option-icon">${folder.id?'▱':'◆'}</span>${esc(folder.name)}</button>`).join('')}</div>`,button('new-folder-in-picker','New folder')+button('close-modal','Cancel')+button('confirm-modal','Pin','class="primary"'));}
else if(modal.type==='name'){const value=item(modal.ids[modal.index]);html=dialog('Name and pin',`<p>${modal.index+1} / ${modal.ids.length} · Enter saves and advances; Esc leaves the rest unchanged.</p>${value?.kind==='image'?`<img class="modal-image" src="${attr(thumbnail(value))}" alt="Selected image">`:`<div class="name-preview">${esc(value?.text||value?.url||'')}</div>`}<label class="dialog-label" for="name-input">${esc(t('Name'))}</label><input id="name-input" value="${attr(modal.name||'')}" maxlength="200" autocomplete="off">`,button('close-modal','Cancel')+button('confirm-modal',modal.index<modal.ids.length-1?'Save and next':'Pin','class="primary"'));}
else if(modal.type==='tags'){const tags=[...new Set(state.items.flatMap(value=>value.tags||[]))].sort().filter(value=>fold(value).includes(fold(modal.query||'')));html=dialog('Add tags',`<p>${modal.ids.length} selected. Comma-separated names add tags without removing existing tags.</p><input id="tags-input" value="${attr(modal.value||'')}" placeholder="project, ideas" aria-label="Tags"><div class="dialog-list">${tags.map(tag=>`<button class="dialog-option" data-action="pick-tag" data-tag="${attr(tag)}"># ${esc(tag)}</button>`).join('')}</div>`,button('close-modal','Cancel')+button('confirm-modal','Apply','class="primary"'));}
else if(modal.type==='record'){html=dialog('Record shortcut',`<p>${esc(modal.global?'Use a modifier with a key. Esc cancels; Backspace turns this shortcut off.':'Press the shortcut for '+ACTION_TITLES[modal.action]+'. Esc cancels; Backspace turns it off.')}</p><div class="record-wait" tabindex="0">${esc(modal.key||'Press keys…')}</div>`,button('close-modal','Cancel')+button('confirm-modal','Save','class="primary"'));}
else if(modal.type==='confirm'){html=dialog(modal.title,`<p>${esc(modal.message)}</p>`,button('close-modal','Cancel')+button('confirm-modal',modal.label||'Move to Trash','class="danger"'));}
else{html=dialog(modal.title||'New folder',`<p>${esc(modal.description||'')}</p><label class="dialog-label" for="simple-input">${esc(modal.label||'Name')}</label>${modal.multiline?`<textarea id="simple-input" rows="5">${esc(modal.value||'')}</textarea>`:`<input id="simple-input" value="${attr(modal.value||'')}" maxlength="500" autocomplete="off">`}`,button('close-modal','Cancel')+button('confirm-modal','Save','class="primary"'));}overlays.innerHTML=html;return;}
if(ui.preview){renderPreview();return;}overlays.innerHTML='';}
function renderPreview(){const value=item(ui.preview);if(!value){ui.preview=null;overlays.innerHTML='';return;}const editor=ui.editor;const values=ui.view==='library'?libraryItems():rowItems(value.kind);const position=Math.max(0,values.findIndex(entry=>entry.id===value.id))+1;let tools='';if(editor){tools=`${[['select','↖'],['pen','✎'],['marker','▰'],['rectangle','□'],['ellipse','○'],['arrow','↗'],['line','╱'],['text','T'],['crop','⌗']].map(([tool,symbol])=>`<button data-action="image-tool" data-tool="${tool}" aria-pressed="${editor.tool===tool}" title="${attr(tool)}">${symbol}</button>`).join('')}<input type="color" id="ink-color" value="${editor.color}" aria-label="Annotation color"><select id="ink-width" aria-label="Stroke width">${[3,7,14,25].map(width=>`<option value="${width}" ${editor.width===width?'selected':''}>${width}px</option>`).join('')}</select><label class="check-label" style="font-size:10px">Fill<input type="checkbox" id="ink-fill" ${editor.fill?'checked':''} aria-label="Fill shapes"></label><select id="text-size" aria-label="Text size">${[24,40,64,96].map(size=>`<option value="${size}" ${editor.fontSize===size?'selected':''}>${size}px</option>`).join('')}</select><button data-action="image-undo" title="Undo">↶</button><button data-action="image-redo" title="Redo">↷</button>${button('reset-image-edits','Reset','title="Reset crop and annotations"')}${button('save-image','Done','class="primary"')}<span class="divider"></span>`;}
let body='';if(value.kind==='image')body=`<div class="image-stage ${ui.zoom>1?'zoomed':''}"><div class="image-document" style="transform:translate(${ui.pan.x}px,${ui.pan.y}px) scale(${ui.zoom})">${editor?'<canvas id="markup-canvas" tabindex="0" aria-label="Image markup canvas"></canvas>':`<img src="${attr(thumbnail(value))}" alt="${attr(title(value))}" draggable="false">`}</div></div>`;else if(value.kind==='text')body=ui.editingText?`<textarea id="text-editor" class="text-editor" aria-label="Edit text">${esc(ui.textDraft)}</textarea>`:`<pre class="preview-text">${esc(value.text)}</pre>`;else body=`<article class="link-preview">${thumbnail(value)?`<img src="${attr(thumbnail(value))}" alt="Link thumbnail">`:''}<h2>${esc(title(value))}</h2><p>${esc(value.author||hostname(value.url))}</p><p>${esc(value.url)}</p>${button('open','Open in browser')} <kbd>Ctrl+O</kbd></article>`;
overlays.innerHTML=`<div class="modal-backdrop"><section class="dialog preview-dialog" id="preview-dialog" role="dialog" aria-modal="true" aria-label="${attr(title(value))}"><div class="preview-toolbar">${tools}<div class="grow"></div><button data-action="previous" aria-label="Previous item">‹</button><span class="position">${position} / ${values.length}</span><button data-action="next" aria-label="Next item">›</button><button data-action="copy" title="${attr(t('Copy'))}">⧉</button><button data-action="pin" aria-pressed="${value.pinned}" title="${attr(t('Pin'))}">◆</button>${value.kind==='image'&&!editor?`<button data-action="markup" title="Image markup · M">✎</button><button data-action="crop" title="Crop image · C">⌗</button>`:''}${value.kind==='text'?button(ui.editingText?'finish-text':'edit',ui.editingText?'Done':'Edit text'):''}<button data-action="actions" title="${attr(t('Actions'))}">⌘</button><button data-action="close-preview" aria-label="${attr(t('Close'))}">×</button></div><div class="preview-body">${body}</div><footer class="preview-footer"><span>${esc(value.name||t(TITLES[value.kind]))}</span><span class="grow"></span><span>${editor?(editor.tool==='crop'?'Drag crop · Enter apply · Esc cancel':'Space+drag pan · Ctrl+Z undo · Ctrl+S save'):'← → items · ↑ ↓ shelves · Enter copy · Ctrl+Enter paste'}</span></footer></section></div>`;
if(editor)requestAnimationFrame(drawEditor);}
function actionCommands(){const ids=ui.modal?.contextIds||selectedIds(), value=item(ids[0]);const commands=[
 ...['search','library','copy','paste','preview','pin','pinnedOnly','folder','name','tag','remove','undo','export','trash','open','copyOCR','markup','crop','edit'].map(id=>({id,title:ACTION_TITLES[id],key:hotkey(id),detail:['copy','paste','pin','folder','name','tag','export','trash','remove'].includes(id)?`${ids.length} selected`:'',disabled:!ids.length&&!['search','library','pinnedOnly','undo'].includes(id)||['markup','crop','copyOCR'].includes(id)&&value?.kind!=='image'||id==='edit'&&value?.kind!=='text'||id==='open'&&value?.kind!=='link'})),
 {id:'new-note',title:'New note',icon:'≡'},{id:'new-folder',title:'New folder',icon:'▱'},{id:'import',title:'Import',icon:'↓'},{id:'capture',title:'Screenshot',icon:'⌗'},
 {id:'scope-saved',title:'My library'},{id:'scope-recent',title:'Recent copies'},{id:'scope-pinned',title:'Pinned'},{id:'scope-trash',title:'Trash'},
 {id:'settings',title:'Settings'},{id:'check-updates',title:'Check for updates'},{id:'hide',title:'Hide'},{id:'quit',title:'Quit ClipBoardLine'}];return commands;}
function select(value,extend=false,toggle=false){if(!value)return;const values=ui.view==='library'?libraryItems():rowItems(value.kind);ui.active=value.kind;const index=values.findIndex(entry=>entry.id===value.id);if(extend&&ui.anchor){const anchor=values.findIndex(entry=>entry.id===ui.anchor);ui.selected=new Set(values.slice(Math.min(anchor,index),Math.max(anchor,index)+1).map(entry=>entry.id));}else if(toggle){ui.selected.has(value.id)?ui.selected.delete(value.id):ui.selected.add(value.id);ui.anchor=value.id;}else{ui.selected=new Set([value.id]);ui.anchor=value.id;}ui.focus=value.id;if(ui.view!=='library')ui.pages[value.kind]=Math.floor(Math.max(0,index)/9);}
function revealFocused(){requestAnimationFrame(()=>root.querySelector(`[data-item-id="${ui.focus}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'}));}
async function move(delta,{extend=false,boundary=false,page=false,vertical=false}={}){if(ui.editingText&&!await finishText())return;if(ui.editor&&!await saveImage(false))return;let values=currentItems();if(ui.preview){const value=item(ui.preview);if(value)ui.active=value.kind;values=ui.view==='library'?libraryItems():rowItems(ui.active);}
if(vertical&&ui.view!=='library'&&(ui.searchOpen||ui.preview)){const kinds=visibleKinds();let index=kinds.indexOf(ui.active)+delta;const current=values.findIndex(value=>value.id===(ui.preview||ui.focus));while(index>=0&&index<kinds.length){const next=rowItems(kinds[index]);if(next.length){ui.active=kinds[index];const value=next[Math.max(0,Math.min(current,next.length-1))];select(value);if(ui.preview)ui.preview=value.id;ui.zoom=1;ui.pan={x:0,y:0};render();return;}index+=delta;}return;}
if(!values.length)return;let index=values.findIndex(value=>value.id===(ui.preview||ui.focus));if(index<0)index=0;const columns=ui.view==='library'&&!ui.list?Math.max(1,Math.floor((document.querySelector('.library-results')?.clientWidth||700)/190)):1;const next=boundary?(delta<0?0:values.length-1):Math.max(0,Math.min(values.length-1,index+delta*(page?9:vertical?columns:1)));select(values[next],extend);if(ui.preview)ui.preview=values[next].id;ui.zoom=1;ui.pan={x:0,y:0};render();revealFocused();}
async function finishText(){if(!ui.editingText)return true;const result=await command('editText',{id:ui.preview,text:ui.textDraft});if(!result)return false;ui.editingText=false;renderOverlay();return true;}
async function flushPreview(){if(!await finishText())return false;if(ui.editor&&!await saveImage(false))return false;return true;}
async function openPreview(id){if(!await flushPreview())return;const value=item(id||ui.focus);if(!value)return;ui.preview=value.id;ui.active=value.kind;ui.editingText=false;ui.editor=null;ui.zoom=1;ui.pan={x:0,y:0};renderOverlay();}
async function closePreview(){if(!await flushPreview())return;ui.preview=null;ui.editor=null;ui.editingText=false;render();}
async function copySelection(keepOpen=false,paste=false,capturedIds=null){if(!await flushPreview())return;const ids=capturedIds||selectedIds();if(!ids.length){toast('Select an item first.');return;}const result=await command(paste?'paste':'copy',{ids,keepOpen});if(!result)return;if(keepOpen){toast(t('Copied'));return;}ui.preview=null;ui.modal=null;ui.editor=null;ui.search='';ui.searchOpen=false;ui.justHidden=true;focusFirst();render();}
async function takeDown(ids=selectedIds()){if(!ids.length||!await flushPreview())return;const values=currentItems();const at=Math.max(0,values.findIndex(value=>value.id===(ui.preview||ui.focus)));const restore=ui.preview||ui.focus;const remaining=values.filter(value=>!ids.includes(value.id));const next=remaining[Math.min(at,remaining.length-1)];const hadPreview=!!ui.preview;const result=await command('remove',{ids});if(!result)return;ui.undoFocus.push({id:restore,preview:hadPreview,kind:ui.active});if(ui.undoFocus.length>32)ui.undoFocus.shift();ui.selected=new Set(next?[next.id]:[]);ui.focus=next?.id||null;ui.preview=hadPreview?next?.id||null:null;ui.editor=null;ui.zoom=1;ui.pan={x:0,y:0};render();}
async function undoTakeDown(){const last=ui.undoFocus.pop();const result=await command('undo');if(result&&last&&item(last.id)){ui.active=last.kind;select(item(last.id));if(last.preview)ui.preview=last.id;render();}}
function startName(ids=selectedIds()){const values=ids.map(item).filter(Boolean);if(!values.length)return;openModal({type:'name',ids:values.map(value=>value.id),index:0,name:values[0].name||''});setTimeout(()=>document.getElementById('name-input')?.select(),0);}
function startFolder(ids=selectedIds()){if(ids.length)openModal({type:'folder',ids:[...ids],query:'',index:0});}
function startTags(ids=selectedIds()){if(ids.length)openModal({type:'tags',ids:[...ids],value:'',query:''});}
async function confirmModal(){const modal=ui.modal;if(!modal||modal.saving)return;modal.saving=true;try{
 if(modal.type==='actions'){const option=currentModalOptions()[modal.index||0];if(option&&!option.disabled){const ids=modal.contextIds;closeModal();await perform(option.id,ids);}return;}
 if(modal.type==='folder'){const option=currentModalOptions()[modal.index||0];if(!option)return;const result=await command(option.id?'folder':'pin',option.id?{ids:modal.ids,folderId:option.id}:{ids:modal.ids,value:true});if(result)closeModal();return;}
 if(modal.type==='name'){const value=modal.name?.trim()||'';const result=await command('name',{ids:[modal.ids[modal.index]],name:value});if(!result)return;if(modal.index<modal.ids.length-1){modal.index++;modal.name=item(modal.ids[modal.index])?.name||'';renderOverlay();setTimeout(()=>document.getElementById('name-input')?.select(),0);}else closeModal();return;}
 if(modal.type==='tags'){const tags=(modal.value||'').split(',').map(value=>value.trim()).filter(Boolean);for(const id of modal.ids){const value=item(id);if(value&&!await command('tag',{ids:[id],tags:[...new Set([...(value.tags||[]),...tags])]}))return;}closeModal();return;}
 if(modal.type==='record'){const key=modal.key||'';const result=await command('setSettings',{patch:{[modal.global?'shortcuts':'localShortcuts']:{[modal.action]:modal.global?key.replace('Ctrl+','Control+'):key}}});if(result)closeModal();return;}
 if(modal.type==='confirm'){const result=await command(modal.command,modal.payload);if(result){ui.selected.clear();ui.preview=null;ui.focus=null;closeModal();focusFirst();render();}return;}
 if(modal.type==='new-folder'){const name=modal.value?.trim();if(!name)return;const result=await command('createFolder',{name,parentId:modal.parentId||null});if(result){if(modal.returnTo){ui.modal=modal.returnTo;renderOverlay();}else closeModal();}return;}
 if(modal.type==='rename-folder'){if(await command('renameFolder',{id:modal.id,name:modal.value.trim()}))closeModal();return;}
 if(modal.type==='new-note'){const result=await command('newNote',{text:modal.value||'New note'});if(result){closeModal();ui.scope='recent';await command('library');if(result.result?.id){select(item(result.result.id));await openPreview(result.result.id);ui.textDraft=item(result.result.id)?.text||'';ui.editingText=true;renderOverlay();setTimeout(()=>document.getElementById('text-editor')?.focus(),0);}}return;}
 if(modal.type==='annotation'){if(ui.editor&&modal.value){checkpoint();const mark={id:++annotationSequence,type:'text',x:modal.x,y:modal.y,text:modal.value,color:ui.editor.color,fontSize:ui.editor.fontSize||40,widthPx:ui.editor.width};if(modal.annotationIndex!=null)ui.editor.annotations[modal.annotationIndex]=mark;else ui.editor.annotations.push(mark);ui.editor.dirty=true;}closeModal();drawEditor();return;}
 }finally{modal.saving=false;}}
async function perform(action,capturedIds=null){const ids=capturedIds||selectedIds();const value=item(ids[0]);switch(action){
case 'shelves':ui.search='';ui.searchOpen=false;ui.preview=null;ui.modal=null;await command('show');focusFirst();render();break;
case 'library':if(!await flushPreview())break;ui.preview=null;ui.search='';ui.searchOpen=false;await command('library');focusFirst();render();break;
case 'settings':if(!await flushPreview())break;ui.preview=null;ui.modal=null;await command('settings');break;
case 'hide':if(!await flushPreview())break;ui.preview=null;ui.modal=null;ui.search='';ui.searchOpen=false;ui.justHidden=true;await command('hide');focusFirst();render();break;
case 'copy':await copySelection(true,false,ids);break;
case 'paste':await copySelection(false,true,ids);break;
case 'preview':if(ui.preview)await closePreview();else await openPreview(ids[0]);break;
case 'close-preview':await closePreview();break;
case 'previous':await move(-1);break;case 'next':await move(1);break;
case 'up':await move(-1,{vertical:true});break;case 'down':await move(1,{vertical:true});break;
case 'first':await move(-1,{boundary:true});break;case 'last':await move(1,{boundary:true});break;
case 'previousPage':await move(-1,{page:true});break;case 'nextPage':await move(1,{page:true});break;
case 'pin':if(ids.length)await command('pin',{ids});break;
case 'pinnedOnly':if(ui.view==='library'){ui.scope=ui.scope==='pinned'?'saved':'pinned';focusFirst();}else{ui.pinned[ui.active]=!ui.pinned[ui.active];if(ui.preview){const values=rowItems(ui.active);ui.preview=values[0]?.id||null;}focusFirst();}render();break;
case 'folder':startFolder(ids);break;case 'name':startName(ids);break;case 'tag':startTags(ids);break;
case 'remove':await takeDown(ids);break;case 'undo':await undoTakeDown();break;
case 'trash':case 'delete':if(ids.length)openModal({type:'confirm',title:action==='delete'?'Delete permanently':'Move to Trash',label:action==='delete'?'Delete permanently':'Move to Trash',message:action==='delete'?`Permanently remove ${ids.length} records? This cannot be undone.`:`Move ${ids.length} selected records to recoverable Library Trash?`,command:action,payload:{ids}});break;
case 'restore':if(ids.length)await command('restore',{ids});break;
case 'export':if(ids.length)await command('export',{ids});break;
case 'open':if(value?.kind==='link')await command('openLink',{id:value.id});break;
case 'copyOCR':if(value?.kind==='image'){toast('Recognizing image text…');const result=await command('ocr',{id:value.id});if(result){const text=result.result?.text||item(value.id)?.ocrText||'';if(text){await command('copyOCR',{id:value.id}).then(copy=>{if(!copy)toast(text.slice(0,160));});}else toast('No readable text found.');}}break;
case 'edit':if(value?.kind==='text'){if(!ui.preview)await openPreview(value.id);ui.textDraft=value.text||'';ui.editingText=true;renderOverlay();setTimeout(()=>document.getElementById('text-editor')?.focus(),0);}break;
case 'finish-text':await finishText();break;
case 'markup':if(value?.kind==='image'){if(ui.editor)await saveImage(true);else{if(!ui.preview)await openPreview(value.id);await beginImageEdit('select');}}break;
case 'crop':if(value?.kind==='image'){if(!ui.preview)await openPreview(value.id);await beginImageEdit('crop');}break;
case 'actions':openModal({type:'actions',query:'',index:0,contextIds:[...ids]});break;
case 'search':if(ui.view==='settings')await command('show');ui.searchOpen=true;render();setTimeout(()=>document.getElementById('search-input')?.focus(),0);break;
case 'librarySearch':if(ui.view==='library')document.getElementById('search-input')?.focus();break;
case 'selectAll':ui.selected=new Set(currentItems().map(value=>value.id));render();break;
case 'switchShelf':{const kinds=visibleKinds();ui.active=kinds[(kinds.indexOf(ui.active)+1)%kinds.length];select(rowItems(ui.active)[0]);render();break;}
case 'toggleImages':case 'toggleTexts':case 'toggleLinks':{const kind=action==='toggleImages'?'image':action==='toggleTexts'?'text':'link';const kinds=visibleKinds();if(kinds.length===1&&kinds.includes(kind)){await perform('hide');break;}await command('setSettings',{patch:{visibleKinds:kinds.includes(kind)?kinds.filter(value=>value!==kind):KINDS.filter(value=>kinds.includes(value)||value===kind)}});focusFirst();render();break;}
case 'toggleShelves':await command('setSettings',{patch:{visibleKinds:visibleKinds().length===1?KINDS:[ui.active]}});break;
case 'allTypes':case 'images':case 'texts':case 'links':if(ui.view==='library'){ui.type={allTypes:'all',images:'image',texts:'text',links:'link'}[action];focusFirst();render();}break;
case 'new-note':openModal({type:'new-note',title:'New note',label:'Content',value:'',multiline:true});break;
case 'new-folder':openModal({type:'new-folder',title:'New folder',value:'',parentId:ui.scope==='folder'?ui.folder:null});break;
case 'capture':await command('capture');break;case 'import':await command('import');break;
case 'check-updates':ui.settingsTab='updates';await command('settings');await command('checkUpdates');break;
case 'install-update':await command('installUpdate');break;
case 'quit':if(await flushPreview())await command('quit');break;
default:if(action.startsWith('scope-')){ui.scope=action.slice(6);ui.search='';await command('library');focusFirst();render();}break;
}}
async function beginImageEdit(tool='select'){const value=item(ui.preview);if(value?.kind!=='image')return;if(ui.editor){if(tool==='crop')ui.editor.beforeCrop=clone(ui.editor.crop);ui.editor.tool=tool;renderOverlay();return;}const image=new Image();const editor={id:value.id,tool,base:image,annotations:clone(value.annotations||[]),crop:clone(value.crop),beforeCrop:clone(value.crop),color:'#ff5252',width:7,fontSize:40,selected:null,history:[],redo:[],dirty:false};ui.editor=editor;ui.zoom=1;ui.pan={x:0,y:0};image.onload=()=>{if(ui.editor!==editor)return;renderOverlay();};image.onerror=()=>{if(ui.editor===editor){ui.editor=null;toast('The original image could not be opened.');renderOverlay();}};image.src=value.originalMediaUrl||value.mediaUrl;renderOverlay();}
function clone(value){return value==null?value:JSON.parse(JSON.stringify(value));}
function editorSnapshot(){return{annotations:clone(ui.editor.annotations),crop:clone(ui.editor.crop)};}
function checkpoint(){if(!ui.editor)return;ui.editor.history.push(editorSnapshot());if(ui.editor.history.length>80)ui.editor.history.shift();ui.editor.redo=[];}
function imageUndo(redo=false){const editor=ui.editor;if(!editor)return;const from=redo?editor.redo:editor.history;if(!from.length)return;(redo?editor.history:editor.redo).push(editorSnapshot());const snapshot=from.pop();editor.annotations=clone(snapshot.annotations);editor.crop=clone(snapshot.crop);editor.selected=null;editor.dirty=true;drawEditor();}
function annotationsBounds(annotation){if(annotation.points?.length){const xs=annotation.points.map(point=>point.x),ys=annotation.points.map(point=>point.y);return{x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys)};}if(annotation.type==='text')return{x:annotation.x,y:annotation.y-(annotation.fontSize||40),width:Math.max(...String(annotation.text).split('\n').map(line=>line.length))*(annotation.fontSize||40)*.62,height:String(annotation.text).split('\n').length*(annotation.fontSize||40)*1.25};return{x:Math.min(annotation.x,annotation.x+annotation.width),y:Math.min(annotation.y,annotation.y+annotation.height),width:Math.abs(annotation.width),height:Math.abs(annotation.height)};}
function drawAnnotations(context,annotations){for(const annotation of annotations){context.save();context.strokeStyle=annotation.color||'#ff5252';context.fillStyle=annotation.color||'#ff5252';context.lineWidth=annotation.widthPx||annotation.strokeWidth||7;context.lineCap='round';context.lineJoin='round';if(annotation.type==='pen'||annotation.type==='marker'){context.lineWidth=annotation.widthPx||7;if(annotation.type==='marker'){context.globalAlpha=.32;context.lineWidth*=3;}context.beginPath();(annotation.points||[]).forEach((point,index)=>index?context.lineTo(point.x,point.y):context.moveTo(point.x,point.y));context.stroke();}
else if(annotation.type==='rectangle'){context.strokeRect(annotation.x,annotation.y,annotation.width,annotation.height);if(annotation.fill){context.globalAlpha=.18;context.fillRect(annotation.x,annotation.y,annotation.width,annotation.height);}}
else if(annotation.type==='ellipse'){const b=annotationsBounds(annotation);context.beginPath();context.ellipse(b.x+b.width/2,b.y+b.height/2,Math.max(1,b.width/2),Math.max(1,b.height/2),0,0,Math.PI*2);context.stroke();if(annotation.fill){context.globalAlpha=.18;context.fill();}}
else if(annotation.type==='line'||annotation.type==='arrow'){const end={x:annotation.x+annotation.width,y:annotation.y+annotation.height};context.beginPath();context.moveTo(annotation.x,annotation.y);context.lineTo(end.x,end.y);context.stroke();if(annotation.type==='arrow'){const angle=Math.atan2(annotation.height,annotation.width),head=Math.max(18,context.lineWidth*4);context.beginPath();context.moveTo(end.x-head*Math.cos(angle-.5),end.y-head*Math.sin(angle-.5));context.lineTo(end.x,end.y);context.lineTo(end.x-head*Math.cos(angle+.5),end.y-head*Math.sin(angle+.5));context.stroke();}}
else if(annotation.type==='text'){context.font=`${annotation.fontSize||40}px Segoe UI, sans-serif`;String(annotation.text).split('\n').forEach((line,index)=>context.fillText(line,annotation.x,annotation.y+index*(annotation.fontSize||40)*1.25));}context.restore();}}
function drawEditor(){const editor=ui.editor,canvas=document.getElementById('markup-canvas');if(!editor||!canvas||!editor.base.complete||!editor.base.naturalWidth)return;const width=editor.base.naturalWidth,height=editor.base.naturalHeight;if(width*height>80000000){toast('Image exceeds the editable pixel limit.');return;}if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}const c=canvas.getContext('2d');c.clearRect(0,0,width,height);c.drawImage(editor.base,0,0);drawAnnotations(c,editor.annotations);if(editor.tool==='crop'&&editor.crop){const b=editor.crop;c.save();c.fillStyle='#0009';c.fillRect(0,0,width,b.y);c.fillRect(0,b.y+b.height,width,height-b.y-b.height);c.fillRect(0,b.y,b.x,b.height);c.fillRect(b.x+b.width,b.y,width-b.x-b.width,b.height);c.strokeStyle='#95d5ff';c.lineWidth=Math.max(2,width/500);c.strokeRect(b.x,b.y,b.width,b.height);const size=Math.max(10,width/90);for(const x of[b.x,b.x+b.width])for(const y of[b.y,b.y+b.height]){c.fillStyle='#ffffff';c.fillRect(x-size/2,y-size/2,size,size);}c.restore();}if(editor.selected!=null&&editor.annotations[editor.selected]){const b=annotationsBounds(editor.annotations[editor.selected]);c.save();c.strokeStyle='#84c8ff';c.lineWidth=Math.max(2,width/700);c.setLineDash([width/130,width/200]);c.strokeRect(b.x-7,b.y-7,b.width+14,b.height+14);c.setLineDash([]);c.fillStyle='#bde7ff';const size=Math.max(12,width/80);c.fillRect(b.x+b.width-size/2,b.y+b.height-size/2,size,size);c.restore();}}
function canvasPoint(event){const canvas=document.getElementById('markup-canvas');const rect=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(canvas.width,(event.clientX-rect.left)/rect.width*canvas.width)),y:Math.max(0,Math.min(canvas.height,(event.clientY-rect.top)/rect.height*canvas.height))};}
function within(point,rect,padding=0){return point.x>=rect.x-padding&&point.x<=rect.x+rect.width+padding&&point.y>=rect.y-padding&&point.y<=rect.y+rect.height+padding;}
function editorPointerDown(event){const editor=ui.editor;if(!editor)return;const point=canvasPoint(event);event.currentTarget?.setPointerCapture?.(event.pointerId);if(ui.spacePan){pointer={type:'pan',x:event.clientX,y:event.clientY,pan:{...ui.pan}};return;}if(editor.tool==='text'){openModal({type:'annotation',title:'Text annotation',label:'Text',value:'',multiline:true,x:point.x,y:point.y});return;}checkpoint();if(editor.tool==='crop'){const crop=editor.crop;const scale=editor.base.naturalWidth/document.getElementById('markup-canvas').getBoundingClientRect().width;const threshold=14*scale;if(crop&&Math.abs(point.x-(crop.x+crop.width))<threshold&&Math.abs(point.y-(crop.y+crop.height))<threshold){pointer={type:'crop-resize',start:point,before:clone(crop)};}else if(crop&&within(point,crop)){pointer={type:'crop-move',start:point,before:clone(crop)};}else{editor.crop={x:point.x,y:point.y,width:1,height:1};pointer={type:'crop-new',start:point};}editor.dirty=true;drawEditor();return;}
if(editor.tool==='select'){let selected=-1;for(let index=editor.annotations.length-1;index>=0;index--){if(within(point,annotationsBounds(editor.annotations[index]),12)){selected=index;break;}}editor.selected=selected<0?null:selected;if(selected>=0){const bounds=annotationsBounds(editor.annotations[selected]);pointer={type:Math.abs(point.x-(bounds.x+bounds.width))<25&&Math.abs(point.y-(bounds.y+bounds.height))<25?'annotation-resize':'annotation-move',start:point,before:clone(editor.annotations[selected]),index:selected};}drawEditor();return;}
const annotation={id:++annotationSequence,type:editor.tool,x:point.x,y:point.y,width:0,height:0,widthPx:editor.width,color:editor.color,fill:!!editor.fill};if(['pen','marker'].includes(editor.tool))annotation.points=[point];editor.annotations.push(annotation);editor.selected=null;editor.dirty=true;pointer={type:'draw',start:point,index:editor.annotations.length-1};drawEditor();}
function editorPointerMove(event){if(!pointer)return;if(pointer.type==='pan'){ui.pan={x:pointer.pan.x+event.clientX-pointer.x,y:pointer.pan.y+event.clientY-pointer.y};updateTransform();return;}if(!ui.editor)return;const editor=ui.editor,point=canvasPoint(event),dx=point.x-pointer.start.x,dy=point.y-pointer.start.y;if(pointer.type==='crop-new'){editor.crop={x:Math.min(point.x,pointer.start.x),y:Math.min(point.y,pointer.start.y),width:Math.max(1,Math.abs(dx)),height:Math.max(1,Math.abs(dy))};}
else if(pointer.type==='crop-move'){const b=pointer.before;editor.crop={...b,x:Math.max(0,Math.min(editor.base.naturalWidth-b.width,b.x+dx)),y:Math.max(0,Math.min(editor.base.naturalHeight-b.height,b.y+dy))};}
else if(pointer.type==='crop-resize'){const b=pointer.before;editor.crop={...b,width:Math.max(1,Math.min(editor.base.naturalWidth-b.x,b.width+dx)),height:Math.max(1,Math.min(editor.base.naturalHeight-b.y,b.height+dy))};}
else if(pointer.type==='annotation-move'){const a=clone(pointer.before);a.x+=dx;a.y+=dy;if(a.points)a.points=a.points.map(p=>({x:p.x+dx,y:p.y+dy}));editor.annotations[pointer.index]=a;editor.dirty=true;}
else if(pointer.type==='annotation-resize'){const a=clone(pointer.before);if(a.type==='text')a.fontSize=Math.max(10,(a.fontSize||40)+dy/3);else if(a.points){const b=annotationsBounds(a),sx=Math.max(.1,(b.width+dx)/Math.max(1,b.width)),sy=Math.max(.1,(b.height+dy)/Math.max(1,b.height));a.points=a.points.map(p=>({x:b.x+(p.x-b.x)*sx,y:b.y+(p.y-b.y)*sy}));}else{a.width+=dx;a.height+=dy;}editor.annotations[pointer.index]=a;editor.dirty=true;}
else if(pointer.type==='draw'){const a=editor.annotations[pointer.index];if(a.points)a.points.push(point);else{let x=dx,y=dy;if(event.shiftKey){if(['rectangle','ellipse'].includes(a.type)){const size=Math.max(Math.abs(x),Math.abs(y));x=Math.sign(x||1)*size;y=Math.sign(y||1)*size;}else{const length=Math.hypot(x,y),angle=Math.round(Math.atan2(y,x)/(Math.PI/4))*Math.PI/4;x=Math.cos(angle)*length;y=Math.sin(angle)*length;}}a.width=x;a.height=y;}}drawEditor();}
async function saveImage(finish=true){const editor=ui.editor;if(!editor)return true;if(!editor.base.naturalWidth){toast('Wait for the original image to load.');return false;}if(editor.dirty){const full=document.createElement('canvas');full.width=editor.base.naturalWidth;full.height=editor.base.naturalHeight;const c=full.getContext('2d');c.drawImage(editor.base,0,0);drawAnnotations(c,editor.annotations);let crop=editor.crop;let output=full;if(crop){crop={x:Math.max(0,Math.round(crop.x)),y:Math.max(0,Math.round(crop.y)),width:Math.max(1,Math.round(crop.width)),height:Math.max(1,Math.round(crop.height))};crop.width=Math.min(crop.width,full.width-crop.x);crop.height=Math.min(crop.height,full.height-crop.y);output=document.createElement('canvas');output.width=crop.width;output.height=crop.height;output.getContext('2d').drawImage(full,crop.x,crop.y,crop.width,crop.height,0,0,crop.width,crop.height);}const result=await command('saveImage',{id:editor.id,dataUrl:output.toDataURL('image/png'),crop,annotations:editor.annotations});if(!result)return false;editor.dirty=false;}if(finish){ui.editor=null;renderOverlay();}return true;}
function updateTransform(){const node=document.querySelector('.image-document');const stage=document.querySelector('.image-stage');if(node&&stage){const bounds=node.getBoundingClientRect();const maxX=Math.max(0,(bounds.width-stage.clientWidth)/2),maxY=Math.max(0,(bounds.height-stage.clientHeight)/2);ui.pan.x=Math.max(-maxX,Math.min(maxX,ui.pan.x));ui.pan.y=Math.max(-maxY,Math.min(maxY,ui.pan.y));}if(node)node.style.transform=`translate(${ui.pan.x}px,${ui.pan.y}px) scale(${ui.zoom})`;}
function eventShortcut(event){const parts=[];if(event.ctrlKey||event.metaKey)parts.push('Ctrl');if(event.altKey)parts.push('Alt');if(event.shiftKey)parts.push('Shift');let key=event.code.startsWith('Key')?event.code.slice(3):event.code.startsWith('Digit')?event.code.slice(5):event.code==='Space'?'Space':event.key;if(['Control','Shift','Alt','Meta'].includes(key))return '';parts.push(key);return parts.join('+');}
function modalKey(event){const modal=ui.modal;if(!modal)return false;if(modal.type==='record'){event.preventDefault();if(event.key==='Escape'){closeModal();return true;}if(event.key==='Backspace'||event.key==='Delete'){modal.key='';renderOverlay();return true;}const shortcut=eventShortcut(event);if(shortcut){modal.key=shortcut;renderOverlay();}return true;}if(event.key==='Escape'){event.preventDefault();closeModal();return true;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='n'&&modal.type==='folder'){event.preventDefault();const back=modal;openModal({type:'new-folder',title:'New folder',value:'',returnTo:back});return true;}if(['actions','folder'].includes(modal.type)&&['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const options=currentModalOptions();let index=modal.index||0;const step=event.key==='ArrowUp'?-1:1;do{index+=step;}while(index>=0&&index<options.length&&options[index].disabled);modal.index=Math.max(0,Math.min(options.length-1,index));const value=document.getElementById('modal-query')?.value||'';renderOverlay();const field=document.getElementById('modal-query');field?.focus();field?.setSelectionRange(value.length,value.length);overlays.querySelector('.dialog-option.selected')?.scrollIntoView({block:'nearest'});return true;}if(event.key==='Enter'&&!event.repeat&&(!(event.target instanceof HTMLTextAreaElement)||event.ctrlKey||event.metaKey)){event.preventDefault();void confirmModal();return true;}return false;}
function isEditor(target){return target instanceof HTMLElement&&(target.matches('input,textarea,select')||target.isContentEditable);}
document.addEventListener('keydown',async event=>{
 if(ui.modal){if(event.key==='Tab'){const controls=[...overlays.querySelectorAll('button:not([disabled]),input,textarea,select,[tabindex="0"]')];const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}modalKey(event);return;}
 const ctrl=event.ctrlKey||event.metaKey;
 if(ui.editingText){if(event.key==='Escape'||ctrl&&event.key==='Enter'){event.preventDefault();await finishText();}return;}
 if(ui.editor){if(ctrl&&event.key.toLowerCase()==='z'){event.preventDefault();imageUndo(event.shiftKey);return;}if(ctrl&&event.key.toLowerCase()==='s'){event.preventDefault();await saveImage(false);return;}if(event.code==='Space'&&!isEditor(event.target)){event.preventDefault();ui.spacePan=true;return;}if(event.key==='Escape'){event.preventDefault();if(ui.editor.tool==='crop'){ui.editor.crop=clone(ui.editor.beforeCrop);ui.editor.tool='select';drawEditor();renderOverlay();}else await saveImage(true);return;}if(event.key==='Enter'){event.preventDefault();if(ui.editor.tool==='crop')await saveImage(true);else if(ctrl)await saveImage(true);return;}if(['Backspace','Delete'].includes(event.key)&&!isEditor(event.target)){event.preventDefault();if(ui.editor.selected!=null){checkpoint();ui.editor.annotations.splice(ui.editor.selected,1);ui.editor.selected=null;ui.editor.dirty=true;drawEditor();}return;}if(!isEditor(event.target)){const toolMap={select:'select',pen:'pen',marker:'marker',rectangle:'rectangle',ellipse:'ellipse',arrow:'arrow',line:'line',annotationText:'text',crop:'crop'};const action=Object.keys(toolMap).find(action=>eventShortcut(event)===hotkey(action));if(action){event.preventDefault();ui.editor.tool=toolMap[action];renderOverlay();return;}}}
 if(isEditor(event.target)){if(ctrl&&event.key.toLowerCase()==='k'){event.preventDefault();await perform('actions');return;}if(event.key==='Escape'&&event.target.id==='search-input'){event.preventDefault();ui.search='';ui.searchOpen=false;focusFirst();render();return;}if(event.target.id==='search-input'&&['Enter','ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();event.target.blur();focusFirst();render();return;}return;}
 if(event.key==='Enter'&&!ctrl&&!event.altKey&&!event.shiftKey){event.preventDefault();await copySelection(false);return;}
 if(event.key==='Escape'){event.preventDefault();if(ui.preview)await closePreview();else if(ui.searchOpen){ui.search='';ui.searchOpen=false;focusFirst();render();}else await perform('hide');return;}
 if(event.code.startsWith('Digit')&&!ctrl&&!event.altKey&&!event.shiftKey&&ui.view==='shelves'&&!ui.preview){const index=Number(event.code.slice(5))-1;const value=rowItems(ui.active)[(ui.pages[ui.active]||0)*9+index];if(index>=0&&index<9&&value){event.preventDefault();select(value);render();}return;}
 if(event.shiftKey&&!ctrl&&!event.altKey&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();await move(['ArrowLeft','ArrowUp'].includes(event.key)?-1:1,{extend:true,vertical:['ArrowUp','ArrowDown'].includes(event.key)});return;}
 let action=Object.keys(DEFAULT_KEYS).find(action=>hotkey(action)&&hotkey(action)===eventShortcut(event));
 if(event.shiftKey&&event.key==='Tab'&&!ctrl&&!event.altKey)action='switchShelf';if(ctrl&&event.shiftKey&&event.key.toLowerCase()==='f')action='pinnedOnly';if(ctrl&&!event.shiftKey&&event.key.toLowerCase()==='p')action='pin';
 if(!action)return;if(ui.view!=='library'&&['librarySearch','allTypes','images','texts','links'].includes(action))return;if(ui.view==='library'&&['library','switchShelf','toggleShelves','toggleImages','toggleTexts','toggleLinks','search','remove','undo'].includes(action)){if(action==='undo'&&event.key==='Backspace')action='trash';else return;}
 if(['select','pen','marker','rectangle','ellipse','arrow','line','annotationText'].includes(action))return;
 event.preventDefault();await perform(action);
});
document.addEventListener('keyup',event=>{if(event.code==='Space'){ui.spacePan=false;pointer=null;}});
async function clickAction(target){const action=target.dataset.action;
 if(action==='close-modal'){closeModal();return;}if(action==='confirm-modal'){await confirmModal();return;}
 if(action==='execute-command'){const chosen=actionCommands().find(value=>value.id===target.dataset.command);if(chosen&&!chosen.disabled){const ids=ui.modal?.contextIds;closeModal();await perform(chosen.id,ids);}return;}
 if(action==='choose-folder'){const modal=ui.modal;if(!modal)return;const folderId=target.dataset.folder;const result=await command(folderId?'folder':'pin',folderId?{ids:modal.ids,folderId}:{ids:modal.ids,value:true});if(result)closeModal();return;}
 if(action==='new-folder-in-picker'){const back=ui.modal;openModal({type:'new-folder',title:'New folder',value:'',returnTo:back});return;}
 if(action==='pick-tag'){const modal=ui.modal;const tags=(modal.value||'').split(',').map(value=>value.trim()).filter(Boolean);if(!tags.includes(target.dataset.tag))tags.push(target.dataset.tag);modal.value=tags.join(', ');renderOverlay();document.getElementById('tags-input')?.focus();return;}
 if(action==='card-pin'){await command('pin',{ids:[target.dataset.id]});return;}if(action==='card-remove'){await takeDown([target.dataset.id]);return;}
 if(action==='activate-shelf'){ui.active=target.dataset.kind;select(rowItems(ui.active)[0]);render();return;}
 if(action==='pinned-kind'){const kind=target.dataset.kind;ui.active=kind;ui.pinned[kind]=!ui.pinned[kind];select(rowItems(kind)[0]);render();return;}
 if(action==='page-back'||action==='page-next'){ui.active=target.dataset.kind;ui.pages[ui.active]=Math.max(0,(ui.pages[ui.active]||0)+(action==='page-next'?1:-1));select(rowItems(ui.active)[ui.pages[ui.active]*9]);render();return;}
 if(action==='close-search'){ui.search='';ui.searchOpen=false;focusFirst();render();return;}
 if(action==='scope'){ui.scope=target.dataset.scope;ui.search='';focusFirst();render();return;}
 if(action==='folder-scope'){ui.scope='folder';ui.folder=target.dataset.folder;ui.search='';focusFirst();render();return;}
 if(action==='tag-scope'){ui.scope='tag';ui.tag=target.dataset.tag;ui.search='';focusFirst();render();return;}
 if(action==='view-mode'){ui.list=!ui.list;render();return;}
 if(action==='clear-filters'){ui.search='';ui.type='all';ui.days=0;ui.domain='';focusFirst();render();return;}
 if(action==='settings-tab'){ui.settingsTab=target.dataset.tab;render();return;}
 if(action==='record-global'||action==='record-local'){openModal({type:'record',action:target.dataset.keyAction,global:action==='record-global',key:action==='record-global'?state.settings.shortcuts[target.dataset.keyAction]:hotkey(target.dataset.keyAction)});return;}
 if(action==='reset-local-shortcuts'){await command('setSettings',{patch:{localShortcuts:{...DEFAULT_KEYS}}});return;}
 if(action==='choose-watch-folder'){await command('chooseWatchFolder');return;}
 if(action==='remove-watch-folder'){const index=state.settings.watchFolders.indexOf(target.dataset.path);if(index>=0)await command('unwatchFolder',{index});return;}
 if(action==='save-detail-name'){const id=selectedIds()[0],name=document.getElementById('detail-name')?.value;if(id&&name!=null)await command('name',{ids:[id],name});return;}
 if(action==='save-detail-text'){const id=selectedIds()[0],text=document.getElementById('detail-text')?.value;if(id&&text!=null)await command('editText',{id,text});return;}
 if(action==='folder-menu'){const id=target.dataset.folder;const folder=state.folders.find(folder=>folder.id===id);if(!folder)return;openModal({type:'actions',query:'',index:0,contextIds:[],folderMenu:id});const options=overlays.querySelector('.dialog-list');if(options)options.innerHTML=`<button class="dialog-option" data-action="rename-folder" data-folder="${id}">Rename folder</button><button class="dialog-option" data-action="new-subfolder" data-folder="${id}">New subfolder</button><button class="dialog-option danger" data-action="remove-folder" data-folder="${id}">Remove folder</button>`;return;}
 if(action==='rename-folder'){const folder=state.folders.find(folder=>folder.id===target.dataset.folder);openModal({type:'rename-folder',title:'Rename folder',id:folder.id,value:folder.name});return;}
 if(action==='new-subfolder'){openModal({type:'new-folder',title:'New folder',value:'',parentId:target.dataset.folder});return;}
 if(action==='remove-folder'){openModal({type:'confirm',title:'Remove folder',label:'Remove folder',message:'Remove this virtual folder? Item content remains in the library.',command:'removeFolder',payload:{id:target.dataset.folder}});return;}
 if(action==='image-tool'){if(ui.editor){ui.editor.tool=target.dataset.tool;if(ui.editor.tool==='crop')ui.editor.beforeCrop=clone(ui.editor.crop);renderOverlay();}return;}
 if(action==='image-undo'){imageUndo();return;}if(action==='image-redo'){imageUndo(true);return;}if(action==='save-image'){await saveImage(true);return;}
 if(action==='reset-image-edits'){if(ui.editor){checkpoint();ui.editor.annotations=[];ui.editor.crop=null;ui.editor.dirty=true;drawEditor();}return;}
 await perform(action);
}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){event.stopPropagation();void clickAction(target);return;}const card=event.target.closest('[data-item-id]');if(card){const value=item(card.dataset.itemId);select(value,event.shiftKey,event.ctrlKey||event.metaKey);render();return;}});
document.addEventListener('dblclick',event=>{const card=event.target.closest('[data-item-id]');if(card&&!event.target.closest('button')){void openPreview(card.dataset.itemId);return;}if(event.target.id==='markup-canvas'&&ui.editor?.tool==='select'&&ui.editor.selected!=null){const annotation=ui.editor.annotations[ui.editor.selected];if(annotation?.type==='text')openModal({type:'annotation',title:'Text annotation',label:'Text',value:annotation.text,multiline:true,x:annotation.x,y:annotation.y,annotationIndex:ui.editor.selected});}else if(event.target.closest('.image-stage')&&!ui.editor){ui.zoom=1;ui.pan={x:0,y:0};updateTransform();}});
document.addEventListener('input',event=>{const target=event.target;if(target.id==='search-input'){const start=target.selectionStart;ui.search=target.value;ui.selected.clear();ui.focus=null;render();const next=document.getElementById('search-input');next?.focus();next?.setSelectionRange(start,start);}
else if(target.id==='modal-query'){const start=target.selectionStart;ui.modal.query=target.value;ui.modal.index=0;renderOverlay();const field=document.getElementById('modal-query');field?.focus();field?.setSelectionRange(start,start);}
else if(target.id==='name-input')ui.modal.name=target.value;
else if(target.id==='tags-input')ui.modal.value=target.value;
else if(target.id==='simple-input')ui.modal.value=target.value;
else if(target.id==='text-editor')ui.textDraft=target.value;
else if(target.id==='shortcut-filter'){const start=target.selectionStart;ui.shortcutsQuery=target.value;render();const field=document.getElementById('shortcut-filter');field?.focus();field?.setSelectionRange(start,start);}
else if(target.id==='domain-filter'){ui.domain=target.value;const start=target.selectionStart;focusFirst();render();const field=document.getElementById('domain-filter');field?.focus();field?.setSelectionRange(start,start);}
else if(target.id==='ink-color'&&ui.editor){ui.editor.color=target.value;if(ui.editor.selected!=null){checkpoint();ui.editor.annotations[ui.editor.selected].color=target.value;ui.editor.dirty=true;drawEditor();}}
});
document.addEventListener('change',event=>{const target=event.target;if(target.dataset.setting){const value=target.type==='checkbox'?target.checked:target.value;void command('setSettings',{patch:{[target.dataset.setting]:value}});}
else if(target.dataset.visibleKind){const kinds=visibleKinds();const next=target.checked?[...new Set([...kinds,target.dataset.visibleKind])]:kinds.filter(kind=>kind!==target.dataset.visibleKind);if(next.length)void command('setSettings',{patch:{visibleKinds:KINDS.filter(kind=>next.includes(kind))}});else{target.checked=true;toast('Keep at least one shelf visible.');}}
else if(target.dataset.retention)void command('setSettings',{patch:{retentionDays:{[target.dataset.retention]:Number(target.value)}}});
else if(target.id==='type-filter'){ui.type=target.value;focusFirst();render();}
else if(target.id==='sort-filter'){ui.sort=target.value;focusFirst();render();}
else if(target.id==='date-filter'){ui.days=Number(target.value);focusFirst();render();}
else if(target.id==='ink-fill'&&ui.editor){ui.editor.fill=target.checked;if(ui.editor.selected!=null){checkpoint();ui.editor.annotations[ui.editor.selected].fill=target.checked;ui.editor.dirty=true;drawEditor();}}else if(target.id==='text-size'&&ui.editor){ui.editor.fontSize=Number(target.value);if(ui.editor.selected!=null&&ui.editor.annotations[ui.editor.selected].type==='text'){checkpoint();ui.editor.annotations[ui.editor.selected].fontSize=Number(target.value);ui.editor.dirty=true;drawEditor();}}else if(target.id==='ink-width'&&ui.editor){ui.editor.width=Number(target.value);if(ui.editor.selected!=null){checkpoint();ui.editor.annotations[ui.editor.selected].widthPx=Number(target.value);ui.editor.dirty=true;drawEditor();}}
});
document.addEventListener('pointerdown',event=>{if(event.target.id==='markup-canvas'){event.preventDefault();editorPointerDown(event);return;}if(event.target.closest('.image-stage')&&ui.zoom>1&&(!ui.editor||ui.spacePan)){event.preventDefault();pointer={type:'pan',x:event.clientX,y:event.clientY,pan:{...ui.pan}};document.querySelector('.image-stage')?.classList.add('panning');}});
document.addEventListener('pointermove',event=>{if(pointer){event.preventDefault();editorPointerMove(event);}});
document.addEventListener('pointerup',()=>{pointer=null;document.querySelector('.image-stage')?.classList.remove('panning');});
document.addEventListener('pointercancel',()=>{pointer=null;});
document.addEventListener('wheel',event=>{if(!ui.preview||item(ui.preview)?.kind!=='image'||!event.target.closest('.image-stage'))return;event.preventDefault();if(event.shiftKey){ui.pan.x-=event.deltaY;ui.pan.y-=event.deltaX;}else{ui.zoom=Math.min(4,Math.max(1,ui.zoom*(event.deltaY<0?1.13:1/1.13)));if(ui.zoom===1)ui.pan={x:0,y:0};}updateTransform();},{passive:false});
document.addEventListener('dragstart',event=>{const card=event.target.closest('[data-item-id]');if(!card)return;const value=item(card.dataset.itemId);if(!ui.selected.has(value.id))select(value);const values=selectedIds().map(item).filter(Boolean);const text=values.filter(value=>value.kind!=='image').map(value=>value.kind==='link'?value.url:value.text).join('\n\n');event.dataTransfer.effectAllowed='copy';if(text)event.dataTransfer.setData('text/plain',text);event.dataTransfer.setData('application/x-clipboardline-ids',JSON.stringify(values.map(value=>value.id)));if(values.some(value=>value.kind==='image')){event.preventDefault();void command('startDrag',{ids:values.map(value=>value.id)}).then(result=>{if(!result)toast('Use Copy or Export to transfer these images.');});}});
window.addEventListener('blur',()=>{ui.spacePan=false;pointer=null;});
if(!api){root.innerHTML='<main class="loading"><h1>ClipBoardLine</h1><p>The secure desktop connection is unavailable. Open this interface through the installed application.</p></main>';root.setAttribute('aria-busy','false');return;}
api.subscribe(next=>{const message=next.message;if(message&&message!==state.message)toast(message);applyState(next);});
api.state().then(applyState).catch(error=>{root.innerHTML=`<main class="loading"><h1>ClipBoardLine</h1><p>${esc(error.message)}</p></main>`;});
})();
